#!/usr/bin/env python3
"""S44 audit, HYP-9316: minimal Cramer weight over monomial ideals generated by pure powers of distinct jet variables
(x_j^e, y_j^e; j <= jmax, e <= emax, any subset -- NOT restricted to downward-closed supports as in S44), with any
window of K+1 CONSECUTIVE jets F_s..F_(s+K) (S44's script only uses s = 0), full rank K checked by random evaluation
mod P (two trials).  Prints the best few ideals.  Usage: python cramer_search.py <curve> [jmax emax Kmax]
"""
import sys, itertools, random
import flint
from curves_audit import Curve, CURVES, P


def main():
    name = sys.argv[1]
    jmax = int(sys.argv[2]) if len(sys.argv) > 2 else 4
    emax = int(sys.argv[3]) if len(sys.argv) > 3 else 4
    Kmax = int(sys.argv[4]) if len(sys.argv) > 4 else 5
    a, b, terms = CURVES[name]
    d = a * terms[0][1] + b * terms[0][2]
    C = Curve(a, b, terms, d + Kmax + 4)
    F = C.F
    qd = lambda code: (a if code % 2 == 0 else b) + code // 2   # total weight of the variable
    variables = [2 * j + v for j in range(jmax + 1) for v in (0, 1)]
    # precompute monomial exponent dicts
    Fm = [[(dict((c, mono.count(c)) for c in set(mono)), co) for mono, co in Fn.items()] for Fn in F]

    def contains(l, gens):
        for cnt, co in Fm[l]:
            if not any(cnt.get(c, 0) >= e for c, e in gens):
                return False
        return True

    def full_rank(window, gens):
        K = len(gens)
        for _ in range(2):
            val = {c: random.randrange(1, P) for c in range(0, 2 * (d + Kmax + 6))}
            rows = []
            for l in window:
                row = [0] * K
                for cnt, co in Fm[l]:
                    for j, (c, e) in enumerate(gens):
                        if cnt.get(c, 0) >= e:
                            r = co
                            for cc, k in cnt.items():
                                kk = k - (e if cc == c else 0)
                                if kk:
                                    r = r * pow(val[cc], kk, P) % P
                            row[j] = (row[j] + r) % P
                            break
                rows.append(row)
            if flint.nmod_mat(K + 1, K, [x for r in rows for x in r], P).rank() == K:
                return True
        return False

    found = []
    for K in range(1, Kmax + 1):
        for vs in itertools.combinations(variables, K):
            for es in itertools.product(range(1, emax + 1), repeat=K):
                gens = list(zip(vs, es))
                hw = sum(e * qd(c) for c, e in gens)
                for s in range(0, 3):
                    window = list(range(s, s + K + 1))
                    if window[-1] >= len(F):
                        break
                    if all(contains(l, gens) for l in window):
                        w = sum(d + l for l in window) - hw
                        if full_rank(window, gens):
                            found.append((w, K, s, tuple(('x' if c % 2 == 0 else 'y') + '%d^%d' % (c // 2, e) for c, e in gens)))
    found.sort()
    print('%s: minimal Cramer weights (w, K, first jet index, generators):' % name)
    for x in found[:6]:
        print('   ', x)


if __name__ == '__main__':
    main()
